package org.ifttw;

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;

/**
 * Starts the IFTTW bot service after the phone boots or the app is updated, without opening the app.
 * It does nothing while every Applet is off (the "all_off" marker file).
 * Registered in AndroidManifest.xml by p4a/hook.py.
 *
 * The ServiceBot class is generated by python-for-android, so it is called through reflection.
 * That keeps this file compilable on its own.
 */
public class BootReceiver extends BroadcastReceiver {
    @Override
    public void onReceive(Context context, Intent intent) {
        if (intent == null || intent.getAction() == null) {
            return;
        }
        String a = intent.getAction();
        if (!Intent.ACTION_BOOT_COMPLETED.equals(a)
                && !Intent.ACTION_MY_PACKAGE_REPLACED.equals(a)
                && !"android.intent.action.QUICKBOOT_POWERON".equals(a)
                && !"com.htc.intent.action.QUICKBOOT_POWERON".equals(a)) {
            return;
        }
        // app.py creates "all_off" in the app data folder while every Applet is off. In that case do not
        // start the service (and its "Running" notification): there is nothing to run.
        if (new java.io.File(context.getFilesDir(), "all_off").exists()) {
            android.util.Log.i("IFTTW", "all Applets are off, service not started at boot");
            return;
        }
        try {
            Class<?> c = Class.forName(context.getPackageName() + ".ServiceBot");
            c.getMethod("start", Context.class, String.class).invoke(null, context, "");
        } catch (Throwable t) {
            android.util.Log.e("IFTTW", "failed to start the service at boot", t);
        }
    }
}
